// MOCK AI OUTPUT - test harness, OFF by default.
// Runs only when "mock_mode" = true in "Settings & normalize".
// No API key, no AI call: simple keyword rules produce the SAME shape
// as the AI Triage Agent ({ output: {...} }), so routing, logging and
// the webhook response can be tested end to end.
// Test markers: [[mock:invalid]] -> malformed AI answer (human review),
//               [[mock:crash]]   -> node failure (error handler).
const { subject = '', message = '', from = '' } = $json;
const text = `${subject}\n${message}`;
const t = text.toLowerCase();

if (t.includes('[[mock:crash]]')) {
  throw new Error('Simulated failure in Mock AI output ([[mock:crash]])');
}
if (t.includes('[[mock:invalid]]')) {
  return { json: { output: { category: 'not_a_category', summary: '' } } };
}

const has = (re) => re.test(t);

// language: count common words per language
const WORDS = {
  en: ['the', 'and', 'my', 'is', 'you', 'please', 'order', 'with', 'have', 'it'],
  de: ['und', 'ich', 'die', 'der', 'nicht', 'meine', 'bitte', 'ist', 'noch', 'habe'],
  fr: ['je', 'le', 'la', 'les', 'et', 'pas', 'mon', 'est', 'vous', 'merci'],
  es: ['el', 'que', 'y', 'mi', 'pedido', 'por', 'gracias', 'es', 'una', 'hola'],
  it: ['il', 'che', 'mio', 'non', 'ordine', 'per', 'sono', 'grazie', 'una', 'ciao'],
  nl: ['het', 'en', 'ik', 'mijn', 'niet', 'bestelling', 'een', 'bedankt', 'is', 'van'],
};
const tokens = t.split(/[^a-zà-ÿß]+/);
let language = 'en';
let best = 0;
for (const [lang, words] of Object.entries(WORDS)) {
  const score = tokens.filter((w) => words.includes(w)).length;
  if (score > best) { best = score; language = lang; }
}

// category: first matching rule wins
const RULES = [
  ['spam', /\b(seo|backlinks?|crypto|bitcoin|casino|guest post|click here|limited offer|investment opportunity)\b/],
  ['wholesale_inquiry', /\b(wholesale|bulk|distributor|reseller|resell|trade pricing|trade price|b2b|großhandel|grossiste)\b/],
  ['complaint', /(unacceptable|disgusting|worst|terrible service|vomit|sick|the vet|lawyer|chargeback|post a review|nobody has replied|third time)/],
  ['return_refund', /(return|refund|exchange|charged twice|double charge|duplicate payment|retourn|rembours|zurücksend|erstatt)/],
  ['delivery_problem', /(damaged|crushed|torn|broken|never received|never got|not received|marked as delivered|says it was delivered|still not here|lost parcel|beschädigt|endommag)/],
  ['order_status', /(where is my order|when will it arrive|when will .* arrive|tracking|no update|haven't had any update|wo bleibt|wann wird|geliefert|versandbestätigung|où en est|ma commande)/],
  ['product_question', /\?|(suitable|do you have|ingredients|size|in stock)/],
];
let category = 'product_question';
let matched = false;
for (const [cat, re] of RULES) {
  if (re.test(t)) { category = cat; matched = true; break; }
}

// urgency
const days = [...t.matchAll(/\b(\d{1,2})\s+(days|tage|jours)\b/g)].map((m) => Number(m[1]));
const veryLate = days.some((d) => d >= 7);
let urgency = 'normal';
if (['spam', 'wholesale_inquiry', 'product_question'].includes(category)) urgency = 'low';
if (has(/(vomit|sick|the vet|chargeback|lawyer|charged twice|duplicate payment|never received|not received|marked as delivered|says it was delivered|urgent|asap)/) || veryLate) urgency = 'high';
if (category === 'spam') urgency = 'low';

// sentiment
let sentiment = 'neutral';
if (has(/(frustrat|unacceptable|disappoint|angry|worst|terrible|sick|vomit|damaged|crushed|torn|never received|charged twice|no answer|nobody has replied)/)) sentiment = 'negative';
else if (has(/(love|great|amazing|thank you so much|happy)/)) sentiment = 'positive';

// extraction
const orderMatch = text.match(/\bPP[-\s]?(\d{5})\b/i);
const order_number = orderMatch ? `PP-${orderMatch[1]}` : null;
const emailInText = message.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
const customer_email = emailInText ? emailInText[0] : (/@/.test(from) ? from : null);
const PRODUCTS = [
  ['kibble', 'Grain-Free Salmon Kibble'],
  ['harness', 'TrailBuddy Reflective Harness'],
  ['litter', 'CalmCat Clumping Litter'],
  ['katzenstreu', 'CalmCat Clumping Litter'],
  ['treats', 'Crunchy Duck Training Treats'],
  ['panier', 'CosyNest Orthopedic Bed'],
  ['bed', 'CosyNest Orthopedic Bed'],
];
const productHit = PRODUCTS.find(([k]) => t.includes(k));
const product = productHit ? productHit[1] : null;

// reply draft (templates; the real agent writes free text)
const SIGN = { en: 'The PawPantry Team', de: 'Ihr PawPantry-Team', fr: "L'équipe PawPantry" };
const BODY = {
  order_status: {
    en: `Thank you for your message. We are checking the status of ${order_number || 'your order'} and will send you the latest tracking details within one business day.`,
    de: `Vielen Dank für Ihre Nachricht. Wir prüfen gerade den Status von ${order_number || 'Ihrer Bestellung'} und senden Ihnen innerhalb eines Werktages die aktuellen Sendungsdaten.`,
    fr: `Merci pour votre message. Nous vérifions le statut de ${order_number || 'votre commande'} et vous enverrons le suivi sous un jour ouvré.`,
  },
  delivery_problem: {
    en: `We are sorry about the trouble with ${order_number || 'your delivery'}. Our team is opening a case with the carrier and will get back to you with a solution within one business day.`,
    de: `Es tut uns leid, dass es Probleme mit ${order_number || 'Ihrer Lieferung'} gibt. Wir klären das mit dem Versanddienstleister und melden uns innerhalb eines Werktages.`,
    fr: `Nous sommes désolés pour le problème avec ${order_number || 'votre livraison'}. Nous ouvrons une réclamation auprès du transporteur et revenons vers vous sous un jour ouvré.`,
  },
  return_refund: {
    en: `Thanks for letting us know. Unused items can be returned free of charge within 30 days. Our team will review ${order_number || 'your request'} and confirm the next steps by email.`,
    de: `Danke für Ihre Nachricht. Unbenutzte Artikel können Sie innerhalb von 30 Tagen kostenlos zurücksenden. Wir prüfen ${order_number || 'Ihre Anfrage'} und bestätigen die nächsten Schritte per E-Mail.`,
    fr: `Merci de nous avoir prévenus. Les articles non utilisés peuvent être retournés gratuitement sous 30 jours. Nous examinons ${order_number || 'votre demande'} et vous confirmons la marche à suivre par e-mail.`,
  },
  product_question: {
    en: 'Thank you for your question. One of our pet-care advisers will reply with a detailed answer within one business day.',
    de: 'Vielen Dank für Ihre Frage. Eine unserer Fachberaterinnen antwortet Ihnen innerhalb eines Werktages ausführlich.',
    fr: 'Merci pour votre question. Un de nos conseillers vous répondra en détail sous un jour ouvré.',
  },
  complaint: {
    en: 'We are very sorry to read this. A team lead will personally look into it and contact you within 24 hours.',
    de: 'Es tut uns sehr leid, das zu lesen. Eine Teamleitung kümmert sich persönlich darum und meldet sich innerhalb von 24 Stunden.',
    fr: 'Nous sommes vraiment désolés. Un responsable va examiner personnellement votre message et vous contactera sous 24 heures.',
  },
  wholesale_inquiry: {
    en: 'Thank you for your interest in working with PawPantry. Our partnerships team will reply within one business day. Could you share your company name, country, VAT number and estimated monthly volume?',
    de: 'Vielen Dank für Ihr Interesse an einer Zusammenarbeit. Unser Partnerteam meldet sich innerhalb eines Werktages. Bitte senden Sie uns Firmenname, Land, USt-IdNr. und das geschätzte Monatsvolumen.',
    fr: 'Merci de votre intérêt pour PawPantry. Notre équipe partenariats vous répondra sous un jour ouvré. Pourriez-vous nous indiquer le nom de votre société, le pays, le numéro de TVA et le volume mensuel estimé ?',
  },
};
BODY.billing = {
  en: `We are sorry about the payment problem with ${order_number || 'your order'}. Our billing team will check the transaction and confirm the correction by email within one business day.`,
  de: `Es tut uns leid, dass es bei ${order_number || 'Ihrer Bestellung'} ein Zahlungsproblem gibt. Unser Buchhaltungsteam prüft die Zahlung und bestätigt die Korrektur innerhalb eines Werktages per E-Mail.`,
  fr: `Nous sommes désolés pour le problème de paiement sur ${order_number || 'votre commande'}. Notre service comptable vérifie la transaction et vous confirme la correction par e-mail sous un jour ouvré.`,
};
const isBilling = category === 'return_refund' && has(/(charged twice|double charge|duplicate payment)/);
const lang = SIGN[language] ? language : 'en';
const body = BODY[isBilling ? 'billing' : category];
const reply_draft = category === 'spam' ? '' : `${body[lang]}\n\n${SIGN[lang]}`;

const LABEL = {
  order_status: 'asks about the status of an order',
  delivery_problem: 'reports a delivery problem',
  return_refund: 'requests a return, refund or billing fix',
  product_question: 'asks a product question',
  complaint: 'complains and expects a personal answer',
  wholesale_inquiry: 'asks about wholesale / trade pricing',
  spam: 'sends unsolicited marketing (spam)',
};
const summary = `[mock] Customer ${LABEL[category]}.${order_number ? ` Order: ${order_number}.` : ''}${product ? ` Product: ${product}.` : ''}`;

return {
  json: {
    output: {
      category,
      urgency,
      sentiment,
      language,
      order_number,
      product,
      customer_email,
      order_status: null,
      summary,
      reply_draft,
      confidence: matched ? 0.9 : 0.55,
    },
  },
};

