// Validates the AI answer (or the mock) and flattens it into one record.
// Anything missing, malformed or low-confidence -> valid = false
// -> "Human review" route. Agent errors (error output) land here too.
// One webhook call = one message, so the request is read with .first():
// paired-item lookups ($('...').item) do not survive an AI Agent that has
// called a tool (n8n 2.44). For batch triggers, run one message per
// execution (e.g. Loop Over Items, batch size 1, before this section).
const settings = $('Settings & normalize').first().json;
const ENUMS = {
  category: ['order_status', 'return_refund', 'product_question', 'delivery_problem', 'complaint', 'wholesale_inquiry', 'spam'],
  urgency: ['low', 'normal', 'high'],
  sentiment: ['positive', 'neutral', 'negative'],
};
const REQUIRED = ['category', 'urgency', 'sentiment', 'language', 'summary', 'reply_draft', 'confidence'];
const errors = [];

let triage = null;
if ($json.error) {
  const msg = typeof $json.error === 'string' ? $json.error : ($json.error.message || JSON.stringify($json.error));
  errors.push(`AI step failed: ${String(msg).slice(0, 300)}`);
} else {
  triage = $json.output;
  if (typeof triage === 'string') {
    try { triage = JSON.parse(triage); } catch (e) { errors.push('AI output is not valid JSON'); triage = null; }
  }
  if (!triage || typeof triage !== 'object' || Array.isArray(triage)) {
    if (!errors.length) errors.push('AI output is missing');
    triage = null;
  }
}

if (triage) {
  for (const field of REQUIRED) {
    if (triage[field] === undefined || triage[field] === null) errors.push(`missing ${field}`);
  }
  for (const [field, allowed] of Object.entries(ENUMS)) {
    if (triage[field] != null && !allowed.includes(triage[field])) errors.push(`invalid ${field}: ${triage[field]}`);
  }
  if (typeof triage.summary === 'string' && !triage.summary.trim()) errors.push('empty summary');
  if (triage.category !== 'spam' && triage.reply_draft != null && !String(triage.reply_draft).trim()) errors.push('empty reply_draft');
  const conf = Number(triage.confidence);
  if (triage.confidence != null && (Number.isNaN(conf) || conf < settings.min_confidence)) {
    errors.push(`low confidence (${triage.confidence})`);
  }
}

const t = triage || {};
const str = (v) => (v === undefined || v === null ? '' : String(v));
return {
  json: {
    received_at: settings.received_at,
    channel: settings.channel,
    sender: settings.from,
    subject: settings.subject,
    message: settings.message,
    category: str(t.category),
    urgency: str(t.urgency),
    sentiment: str(t.sentiment),
    language: str(t.language),
    order_number: str(t.order_number),
    product: str(t.product),
    customer_email: str(t.customer_email),
    order_status: str(t.order_status),
    summary: str(t.summary),
    reply_draft: str(t.reply_draft),
    confidence: Number.isFinite(Number(t.confidence)) ? Number(t.confidence) : 0,
    valid: errors.length === 0,
    validation_errors: errors.join('; '),
    mode: settings.mock_mode === true ? 'mock' : 'live',
  },
};

